// Lane S3: the world playlist (playlist-runtime.mjs, generated by tools/score/import-playlist.mjs) loads without Tone
// doing anything, registers every listed piece once, and each piece composes its first cycles (notes, no audio).
import test from 'node:test';
import assert from 'node:assert/strict';
import { createPlaylistScore, PLAYLIST } from './playlist-runtime.mjs';
import { musicDb } from '../gen-mesh/music.ts';

const inertTone = new Proxy({}, { get: () => function inert() { return undefined; } });

test('the playlist registers each of its pieces once, in order, without touching Tone', () => {
  const Sim = createPlaylistScore(inertTone);
  assert.equal(PLAYLIST.length, 12);
  assert.deepEqual(Sim.pieces.map((p) => p.id), [...PLAYLIST]);
  assert.equal(typeof Sim.Conductor, 'function');
});

test('every piece composes its first three cycles', () => {
  const Sim = createPlaylistScore(inertTone) as unknown as { pieces: { id: string; compose(a: object): { events?: unknown[]; state?: object } }[]; theory: { rng(seed: number): { fork(n: number): unknown } } };
  for (const p of Sim.pieces) {
    const rng = Sim.theory.rng(7); let state = {}, notes = 0;
    for (let cycle = 0; cycle < 3; cycle++) { const r = p.compose({ cycle, rng: rng.fork(cycle), state, T: Sim.theory }) ?? {}; state = r.state ?? state; notes += r.events?.length ?? 0; }
    assert.ok(notes > 20, `${p.id}: ${notes} events`);
  }
});

test('music level follows the master volume; zero is silence', () => {
  assert.equal(musicDb(0), -Infinity);
  assert.ok(musicDb(0.32) < -9 && musicDb(0.32) > -11);
  assert.equal(musicDb(1), 0);
});
